  private resourcePath(file: string): string {
    const path = file.replace(/^resources\//, '').replace(/\.png$/i, '');
    if (!path || path.startsWith('/') || path.split('/').includes('..')) throw new Error('非法本地资源路径');
    return `${this.resourcePrefix}/${path}/spriteFrame`;
  }
  private async loadFrame(file: string): Promise<SpriteFrame> {
    const cached = this.frames.get(file); if (cached) return cached;
    const source = await this.runtimeServices().loadSpriteFrame(this.resourcePath(file));
    if (!this.alive || !isValid(this.node)) throw new Error('组件已销毁');
